Value.Calculation:
Let ( ~d = Get ( CurrentDate ) ;
	Year ( ~d ) & "-" & Right ( "0" & Month ( ~d ) ; 2 ) & "-" & Right ( "0" & Day ( ~d ) ; 2 )
)

Let ( [
	~pm = $periodMode ;
	~monOffset = Mod ( DayOfWeek ( $anchor ) - 2 ; 7 )
] ;
	Case (
		~pm = "week" ; $anchor - ~monOffset ;
		~pm = "month" ; Date ( Month ( $anchor ) ; 1 ; Year ( $anchor ) ) ;
		$anchor
	)
)

Let ( [
	~pm = $periodMode ;
	~monOffset = Mod ( DayOfWeek ( $anchor ) - 2 ; 7 )
] ;
	Case (
		~pm = "week" ; $anchor - ~monOffset + 6 ;
		~pm = "month" ; Date ( Month ( $anchor ) + 1 ; 0 ; Year ( $anchor ) ) ;
		$anchor
	)
)

Let ( [
	~months = List ( "Januar" ; "Februar" ; "Mart" ; "April" ; "Maj" ; "Juni" ; "Juli" ; "Avgust" ; "Septembar" ; "Oktobar" ; "Novembar" ; "Decembar" ) ;
	~mFrom = GetValue ( ~months ; Month ( $fromD ) ) ;
	~mTo = GetValue ( ~months ; Month ( $toD ) ) ;
	~mAnchor = GetValue ( ~months ; Month ( $anchor ) )
] ;
	Case (
		$periodMode = "week" ;
			If ( Month ( $fromD ) = Month ( $toD ) ;
				"Sedmica: " & Day ( $fromD ) & "–" & Day ( $toD ) & ". " & ~mTo & " " & Year ( $toD ) ;
				"Sedmica: " & Day ( $fromD ) & ". " & ~mFrom & " – " & Day ( $toD ) & ". " & ~mTo & " " & Year ( $toD )
			) ;

		$periodMode = "month" ;
			~mAnchor & " " & Year ( $anchor ) ;

		Day ( $anchor ) & ". " & ~mAnchor & " " & Year ( $anchor )
	)
)

If ( IsEmpty ( $query ) ; "" ;
	Let ( ~like = epSQLQuote ( "%" & Lower ( $query ) & "%" ) ;
		" AND ( LOWER ( so.ServiceOrderNumber ) LIKE " & ~like &
		" OR LOWER ( so.Description ) LIKE " & ~like &
		" OR LOWER ( v.PlateNumber ) LIKE " & ~like &
		" OR LOWER ( v.Manufacturer ) LIKE " & ~like &
		" OR LOWER ( v.Model ) LIKE " & ~like &
		" OR LOWER ( c.FirstName ) LIKE " & ~like &
		" OR LOWER ( c.LastName ) LIKE " & ~like &
		" OR LOWER ( c.CompanyName ) LIKE " & ~like &
		" )"
	)
)

JSONSetElement ( "{}" ;
	[ "periodMode" ; $periodMode ; JSONString ] ;
	[ "anchorDate" ; $anchorStr ; JSONString ] ;
	[ "statuses" ; $statuses ; JSONArray ] ;
	[ "query" ; $query ; JSONString ] ;
	[ "offset" ; $offset ; JSONNumber ] ;
	[ "limit" ; $limit ; JSONNumber ]
)

JSONSetElement ( "{}" ;
	[ "id" ; epSQLResult ( $i ; 0 ; "rs_kanban" ) ; JSONString ] ;
	[ "number" ; epSQLResult ( $i ; 1 ; "rs_kanban" ) ; JSONString ] ;
	[ "status" ; epSQLResult ( $i ; 2 ; "rs_kanban" ) ; JSONString ] ;
	[ "customer" ; epSQLResult ( $i ; 3 ; "rs_kanban" ) ; JSONString ] ;
	[ "phone" ; epSQLResult ( $i ; 4 ; "rs_kanban" ) ; JSONString ] ;
	[ "plate" ; epSQLResult ( $i ; 5 ; "rs_kanban" ) ; JSONString ] ;
	[ "make" ; epSQLResult ( $i ; 6 ; "rs_kanban" ) ; JSONString ] ;
	[ "model" ; epSQLResult ( $i ; 7 ; "rs_kanban" ) ; JSONString ] ;
	[ "year" ; GetAsNumber ( epSQLResult ( $i ; 8 ; "rs_kanban" ) ) ; JSONNumber ] ;
	[ "service" ; epSQLResult ( $i ; 9 ; "rs_kanban" ) ; JSONString ] ;
	[ "note" ; epSQLResult ( $i ; 10 ; "rs_kanban" ) ; JSONString ] ;
	[ "date" ; epSQLResult ( $i ; 11 ; "rs_kanban" ) ; JSONString ] ;
	[ "timeStart" ; epSQLResult ( $i ; 12 ; "rs_kanban" ) ; JSONString ] ;
	[ "timeEnd" ; epSQLResult ( $i ; 13 ; "rs_kanban" ) ; JSONString ] ;
	[ "rush" ; GetAsNumber ( epSQLResult ( $i ; 14 ; "rs_kanban" ) ) ; JSONNumber ] ;
	[ "price" ; GetAsNumber ( epSQLResult ( $i ; 15 ; "rs_kanban" ) ) ; JSONNumber ]
)

JSONSetElement ( "{}" ;
	[ "periodMode" ; $periodMode ; JSONString ] ;
	[ "anchorDate" ; $anchorStr ; JSONString ] ;
	[ "from" ; $fromISO ; JSONString ] ;
	[ "to" ; $toISO ; JSONString ] ;
	[ "label" ; $label ; JSONString ] ;
	[ "statuses" ; $statuses ; JSONArray ] ;
	[ "query" ; $query ; JSONString ] ;
	[ "page" ; JSONSetElement ( "{}" ;
		[ "offset" ; $offset ; JSONNumber ] ;
		[ "limit" ; $limit ; JSONNumber ] ;
		[ "total" ; $total ; JSONNumber ] ;
		[ "hasMore" ; $offset + $limit < $total ; JSONBoolean ]
	) ; JSONObject ]
)
